import { Task } from '../domain/Task';
import { TaskRepository } from '../domain/TaskRepository';
import { UserRepository } from '../domain/UserRepository';

export class AssignTaskUseCase {
  constructor(
    private taskRepository: TaskRepository,
    private userRepository: UserRepository,
  ) {}

  execute(taskId: string, assigneeId: string): Task {
    const user = this.userRepository.getById(assigneeId);
    if (!user) {
      throw new Error(`User with id ${assigneeId} not found`);
    }

    const task = this.taskRepository.getById(taskId);
    if (!task) {
      throw new Error(`Task with id ${taskId} not found`);
    }

    const updated = task.withAssignee(assigneeId);
    this.taskRepository.save(updated);
    return updated;
  }
}

