import { Task } from '../domain/Task';
import { TaskRepository } from '../domain/TaskRepository';

export class MarkTaskDoneUseCase {
  constructor(private taskRepository: TaskRepository) {}

  execute(taskId: string): Task {
    const task = this.taskRepository.getById(taskId);
    if (!task) {
      throw new Error(`Task with id ${taskId} not found`);
    }

    if (!task.canMarkDone()) {
      throw new Error('Task is already marked as done');
    }

    const updated = task.withStatus('done');
    this.taskRepository.save(updated);
    return updated;
  }
}

